local modules = {}

table.insert(modules, function()
	local m = {}

	m.ModuleType = "MOVESET"
	m.Name = "Clown V2"
	m.Description = "Made by Mr. Clown"
	m.InternalName = "MOVESET_SOY"

	-- Los archivos ya vienen dentro de este script (EMBEDDED), no se descargan de ningún lado
	m.Assets = {}

	local ASSET_DIR = "Clown_assets"
	local STUN_COPY_DIR = "BlaaBlaaReanim/Content/Anims" -- aquí también se guarda stun.anim

	local B64 = {}
	do
		local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		for i = 1, #chars do B64[chars:byte(i)] = i - 1 end
	end

	-- decodificador base64 propio (funciona en cualquier executor)
	local function b64decode(str)
		local out, buf, n = {}, {}, 0
		local len = #str
		for i = 1, len - 3, 4 do
			local a, b, c, d = str:byte(i, i + 3)
			local v = B64[a] * 262144 + B64[b] * 4096 + (B64[c] or 0) * 64 + (B64[d] or 0)
			local c1, c2, c3 = math.floor(v / 65536), math.floor(v / 256) % 256, v % 256
			n += 1
			buf[n] = string.char(c1, c2, c3)
			if n >= 4096 then
				out[#out + 1] = table.concat(buf, "", 1, n)
				n = 0
			end
		end
		if n > 0 then out[#out + 1] = table.concat(buf, "", 1, n) end
		local res = table.concat(out)
		-- quitar el relleno "=" del final
		if str:sub(-2) == "==" then res = res:sub(1, -3) elseif str:sub(-1) == "=" then res = res:sub(1, -2) end
		return res
	end

	-- escribe los archivos embebidos (solo si faltan o están incompletos)
	local function installAssets()
		if not (writefile and isfile and readfile) then return end
		pcall(function() if makefolder and not (isfolder and isfolder(ASSET_DIR)) then makefolder(ASSET_DIR) end end)
		for name, info in pairs(EMBEDDED) do
			if info.lazy then continue end   -- las canciones de variante se instalan al elegirlas
			local path = ASSET_DIR .. "/" .. name
			local okSize, cur = pcall(function() return isfile(path) and #readfile(path) or -1 end)
			if not okSize or cur ~= info.size then
				pcall(function() writefile(path, b64decode(table.concat(info.data))) end)
			end
		end

		-- copia extra: stun/jump/fall también en la carpeta de animaciones de BlaaBlaaReanim (sin pisar las que ya existan)
		for _, name in ipairs({ "stun.anim", "jump.anim", "fall.anim" }) do
			pcall(function()
				local info = EMBEDDED[name]
				local path = STUN_COPY_DIR .. "/" .. name
				if isfile(path) then return end
				local acc = ""
				for part in STUN_COPY_DIR:gmatch("[^/]+") do
					acc = (acc == "") and part or (acc .. "/" .. part)
					if makefolder and not (isfolder and isfolder(acc)) then pcall(makefolder, acc) end
				end
				writefile(path, b64decode(table.concat(info.data)))
			end)
		end
	end

	-- instala UN archivo embebido (para las canciones de variante, solo cuando se eligen)
	local function ensureAsset(name)
		local info = EMBEDDED[name]
		if not info or not (writefile and isfile and readfile) then return end
		pcall(function() if makefolder and not (isfolder and isfolder(ASSET_DIR)) then makefolder(ASSET_DIR) end end)
		local path = ASSET_DIR .. "/" .. name
		local okSize, cur = pcall(function() return isfile(path) and #readfile(path) or -1 end)
		if not okSize or cur ~= info.size then
			pcall(function() writefile(path, b64decode(table.concat(info.data))) end)
		end
	end

	-- ruta de un archivo: primero el embebido, si no existe usa el del framework
	local function assetPath(file)
		local path = ASSET_DIR .. "/" .. file
		if isfile and isfile(path) then return path end
		return AssetGetPathFromFilename(file)
	end


	-- ── CONFIG DEL STAND ──────────────────────────────────────────────
	-- Username del amigo con el que arrancas. Si lo dejas vacío, arranca con uno
	-- al azar. El botón "Amigo" abre un menú para elegir de tu lista de amigos.
	local FRIEND_USERNAME = ""
	local STAND_OFFSET    = CFrame.new(2.5, 0.5, 3.5) -- derecha/arriba/atrás
	local STAND_FOLLOW    = 12                         -- más alto = sigue más pegado
	local STAND_DANCE_OFFSET = CFrame.new(-5.5, 0, 0.5) -- al bailar: posición del AMIGO 1 (a tu derecha; si queda a la izquierda, cambia el signo). Se multiplica por tu tamaño
	local MAX_FRIENDS     = 6     -- cuántos amigos puedes invocar
	local ROW_SPACING     = 3.5   -- distancia hacia atrás entre filas (caminando)
	local ROW_SPACING_DANCE = 3.2 -- cada fila siguiente se va esto hacia atrás (bailando)
	-- Al bailar los amigos forman una V detrás de ti (3 por lado, abierta hacia atrás)
	local DANCE_BACK_DISTANCE = 3   -- qué tan atrás de ti queda la primera pareja (amigos 1 y 2)
	local DANCE_SIDE_DISTANCE = 3.5 -- qué tan separados a los lados quedan los de la primera pareja
	local DANCE_V_STEP_SIDE   = 2.5 -- cada fila siguiente se abre esto hacia afuera
	local DANCE_BACK_SIGN = 1     -- al bailar: -1 o 1 según hacia dónde es "atrás". Si quedan adelante, cambia el signo
	-- {lado, fila}  lado: 1 = igual que el amigo 1 (derecha), -1 = opuesto (izquierda). fila: 0 = al lado tuyo, 1 = una fila atrás...
	local SLOT_LAYOUT = {
		{  1, 0 },  -- 1: derecha
		{ -1, 0 },  -- 2: izquierda
		{ -1, 1 },  -- 3: atrás del 2 (izquierda)
		{  1, 1 },  -- 4: atrás del 1 (derecha)
		{ -1, 2 },  -- 5: atrás del 3 (izquierda)
		{  1, 2 },  -- 6: atrás del 4 (derecha)
	}

	local Players          = game:GetService("Players")
	local UserInputService = game:GetService("UserInputService")
	local HttpService = game:GetService("HttpService")
	local FAV_FILE    = "Clown_favorites.json"
	local RunService = game:GetService("RunService")

	-- refs
	local figureRef
	local idleAnim, runAnim, walkAnim, stunAnim, jumpAnim, fallAnim
	local animLen = {}   -- duración de las animaciones que no se repiten (para no pasarse del final)
	local currentAnim

	-- stand
	local alive = false
	local slots   = {}   -- [i] = { model, root, pairs, idle, idleT, scale, placed }
	local slotIds = {}   -- [i] = userId del amigo en ese slot
	local slotGen = {}   -- [i] = contador para cancelar cargas viejas
	local activeSlot = 1 -- slot que se llena al tocar un amigo en el menú
	local standT = 0

	-- detección de baile: si la pose de mi figura cambia después de que mi
	-- moveset escribió la suya, otro módulo (un baile) la está controlando
	local figureMotors = {}
	local minePose     = {}
	local danceHold    = 0
	local danceBlend   = 0

	-- speed constants
	local WALK_SPEED   = 15
	local SPRINT_SPEED = 27

	local isSprinting = false

	-- ── STUN (al caer desde un lugar alto) ────────────────────────────
	local STUN_FALL_HEIGHT = 25    -- studs de caída (a tamaño normal) para quedar aturdido. Un salto normal mide ~7
	local STUN_DURATION    = 2.0   -- segundos inmóvil (la animación dura ~1.83 s y se queda en la última pose)
	local STUN_ANIM_LEN    = 1.8333 -- duración de stun.anim (último keyframe)
	local STUN_FADE        = 0.08  -- transición rápida hacia el stun (golpe seco)

	local stunTime     = 0      -- >0 mientras estás aturdido
	local stunLocked   = false  -- true mientras el Humanoid está bloqueado por el stun
	local airborne     = false  -- estoy en el aire (para medir la caída)
	local peakY        = 0      -- punto más alto de la caída actual
	local savedJumpPower, savedJumpHeight, savedUseJP, savedAutoRotate = 50, 7.2, true, true

	-- ── MÚSICA ────────────────────────────────────────────────────────
	local MUSIC_FILE   = "Music_clown.mp3"
	local MUSIC_VOLUME = 0.5     -- volumen de la música
	local music                  -- el Sound
	local musicOn      = true    -- botón "Quitar música" / "Poner música"
	local musicHold    = 0       -- >0 mientras haces un emote (la música se silencia)

	-- ── VARIANTES DE MÚSICA (menú "Music Variant") ──────────────────
	local MUSIC_VARIANTS = {
		{ label = "Normal Music",                  file = "Music_clown.mp3" },
		{ label = "Close To Me",                   file = "Music_closetome.mp3" },
		{ label = "Cipher",                        file = "Music_cipher.mp3" },
		{ label = "GIRL HELL 1999",                file = "Music_girlhell.mp3" },
		{ label = "Dancing With Your Eyes Closed", file = "Music_dancing.mp3" },
		{ label = "Absurdism (Piano)",             file = "Music_absurdism.mp3" },
	}
	m.MusicVariant = 1
	local musicIds = {}   -- [archivo] = id de getcustomasset

	local function musicFile()
		local v = MUSIC_VARIANTS[m.MusicVariant] or MUSIC_VARIANTS[1]
		return v.file
	end

	local function musicAssetId(file)
		if musicIds[file] then return musicIds[file] end
		ensureAsset(file)
		local ok, id = pcall(function()
			local fn = getcustomasset or getsynasset
			return fn(assetPath(file))
		end)
		if ok and id then musicIds[file] = id return id end
		return nil
	end

	local function createMusic()
		local id = musicAssetId(musicFile())
		if not id then return end
		music = Instance.new("Sound")
		music.Name = "Clown_Music"
		music.SoundId = id
		music.Looped = true
		music.Volume = 0
		music.Parent = game:GetService("SoundService")
		if musicOn then music:Play() end
	end

	local function setMusic(on)
		musicOn = on
		if music then
			if on then music:Play() else music:Stop() end
		end
		ContextActions:SetTitle("Uhhhhhh_SoyMusic", on and "Remove music" or "Play music")
	end

	-- sube/baja el volumen suave; silencio total mientras haces un emote
	local function updateMusic(dt, writing)
		if not music then return end
		if writing then musicHold = 0.3 else musicHold = math.max(0, musicHold - dt) end
		local target = (musicOn and musicHold <= 0) and MUSIC_VOLUME or 0
		local v = music.Volume + (target - music.Volume) * (1 - math.exp(-14 * dt))
		if math.abs(v - target) < 0.005 then v = target end
		music.Volume = v
	end

	-- cambia la canción en vivo al elegir otra variante
	local function applyMusicVariant()
		if not music then return end
		local id = musicAssetId(musicFile())
		if not id then return end
		music.SoundId = id
		music.TimePosition = 0
		if musicOn then music:Play() end
	end

	m.Config = function(parent)
		local labels = {}
		for i, v in ipairs(MUSIC_VARIANTS) do labels[i] = v.label end
		Util_CreateDropdown(parent, "Music Variant", labels, m.MusicVariant).Changed:Connect(function(val)
			m.MusicVariant = val
			applyMusicVariant()
		end)
	end

	m.LoadConfig = function(save)
		local v = save and save.MusicVariant
		if type(v) == "number" and MUSIC_VARIANTS[v] then m.MusicVariant = v end
	end

	m.SaveConfig = function()
		return { MusicVariant = m.MusicVariant }
	end

	-- animation helpers
	local function loadAnim(file)
		local anim = AnimLib.Animator.new()
		anim.rig    = figureRef
		anim.track  = AnimLib.Track.fromfile(assetPath(file))
		anim.looped = false
		anim.speed  = 1
		anim.weight = 0
		return anim
	end

	local function loadLoopAnim(file)
		local anim = loadAnim(file)
		anim.looped = true
		return anim
	end

	-- ── TRANSICIONES SUAVES DE ANIMACIÓN ──────────────────────────────
	local FADE_TIME  = 0.25  -- segundos que dura el cruce entre animaciones (idle <-> caminar <-> correr)
	local ACCEL_TIME = 0.45  -- segundos que tarda la animación de caminar/correr en llegar a velocidad completa
	local ACCEL_MIN  = 0.3   -- velocidad inicial de la animación al arrancar (0.3 = 30%)

	local accel        = 0   -- 0 = quieto, 1 = animación a toda velocidad
	local fadeAlpha    = 1   -- 1 = sin transición en curso
	local fadeDur      = FADE_TIME -- duración del cruce actual
	local fadeFromAnim       -- animación de la que venimos (sigue moviéndose mientras se desvanece)
	local fadeFromPose       -- o una pose congelada (si cambias de animación a mitad de una transición)

	local function capturePose()
		local t = {}
		for _, mt in ipairs(figureMotors) do t[mt] = mt.Transform end
		return t
	end

	local function play(anim, ft)
		if currentAnim == anim then return end
		fadeDur = ft or FADE_TIME
		if currentAnim then
			if fadeAlpha < 1 then
				fadeFromPose, fadeFromAnim = capturePose(), nil   -- sin saltos si cambias a mitad
			else
				fadeFromAnim, fadeFromPose = currentAnim, nil
			end
			fadeAlpha = 0
		end
		currentAnim = anim
		anim._t = 0
	end

	local function smooth(x) return x * x * (3 - 2 * x) end

	local function zeroWeights()
		if idleAnim then idleAnim.weight = 0 end
		if runAnim  then runAnim.weight  = 0 end
		if walkAnim then walkAnim.weight = 0 end
		if stunAnim then stunAnim.weight = 0 end
		if jumpAnim then jumpAnim.weight = 0 end
		if fallAnim then fallAnim.weight = 0 end
	end

	local function stepOne(a, dt)
		-- walk/run arrancan lentos y aceleran; el idle va a velocidad normal
		local rate = 1
		if a == walkAnim or a == runAnim then
			rate = ACCEL_MIN + (1 - ACCEL_MIN) * smooth(accel)
		end
		a._t = (a._t or 0) + dt * rate
		local maxT = animLen[a]
		if maxT then a._t = math.min(a._t, maxT) end
		zeroWeights()
		a.weight = 1
		a:Step(a._t)
	end

	local function stepAnims(dt, moving)
		-- aceleración: sube al moverte, baja un poco más rápido al parar
		if moving then
			accel = math.min(1, accel + dt / ACCEL_TIME)
		else
			accel = math.max(0, accel - dt / ACCEL_TIME * 1.5)
		end

		if not currentAnim then return end

		if fadeAlpha >= 1 then
			stepOne(currentAnim, dt)
			return
		end

		fadeAlpha = math.min(1, fadeAlpha + dt / fadeDur)
		local e = smooth(fadeAlpha)

		local from = fadeFromPose
		if fadeFromAnim then
			stepOne(fadeFromAnim, dt)
			from = capturePose()
		end
		stepOne(currentAnim, dt)

		if from then
			for mt, tr in pairs(from) do
				if mt.Parent then mt.Transform = tr:Lerp(mt.Transform, e) end
			end
		end
		if fadeAlpha >= 1 then fadeFromAnim, fadeFromPose = nil, nil end
	end

	-- ── STUN: bloquear / desbloquear ─────────────────────────────────
	local function lockHumanoid(hum)
		if stunLocked then return end
		stunLocked = true
		savedJumpPower, savedJumpHeight, savedUseJP, savedAutoRotate = hum.JumpPower, hum.JumpHeight, hum.UseJumpPower, hum.AutoRotate
		pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, false) end)
	end

	local function unlockHumanoid(hum)
		if not stunLocked then return end
		stunLocked = false
		hum.JumpPower  = savedJumpPower
		hum.JumpHeight = savedJumpHeight
		hum.UseJumpPower = savedUseJP
		hum.AutoRotate = savedAutoRotate
		pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true) end)
	end

	local function startStun()
		if not stunAnim then return end
		stunTime = STUN_DURATION
		airborne = false
		stunAnim._t = 0
		play(stunAnim, STUN_FADE)
	end

	-- ── STAND (amigo NPC, solo lo ves tú) ─────────────────────────────
	local friends       = {}   -- { {Id=, Name=}, ... } ordenados por nombre
	local friendsLoaded = false
	local loadingFriends = false
	local favs          = {}   -- [userId] = true (se guarda en archivo, permanente)

	local function loadFavs()
		pcall(function()
			if isfile and isfile(FAV_FILE) then
				local data = HttpService:JSONDecode(readfile(FAV_FILE))
				for _, id in ipairs(data) do favs[id] = true end
			end
		end)
	end

	local function saveFavs()
		pcall(function()
			local list = {}
			for id in pairs(favs) do table.insert(list, id) end
			writefile(FAV_FILE, HttpService:JSONEncode(list))
		end)
	end

	local function loadFriends()
		if friendsLoaded then return end
		if loadingFriends then
			repeat task.wait() until friendsLoaded or not alive
			return
		end
		loadingFriends = true

		local ok, pages = pcall(Players.GetFriendsAsync, Players, Players.LocalPlayer.UserId)
		if ok and pages then
			for _ = 1, 10 do
				local okPage, page = pcall(function() return pages:GetCurrentPage() end)
				if not okPage then break end
				for _, item in ipairs(page) do
					local name = item.DisplayName
					if name == nil or name == "" then name = item.Username end
					if item.Username and item.Username ~= name then
						name = name .. " (@" .. item.Username .. ")"
					end
					table.insert(friends, { Id = item.Id, Name = name })
				end
				if pages.IsFinished then break end
				if not pcall(function() pages:AdvanceToNextPageAsync() end) then break end
			end
		end

		table.sort(friends, function(x, y) return x.Name:lower() < y.Name:lower() end)
		friendsLoaded  = true
		loadingFriends = false
	end

	-- tamaño de tu figura (reanimate): alto del torso / 2 (R6 normal = 1)
	local function measureScale()
		local t = figureRef and (figureRef:FindFirstChild("Torso") or figureRef:FindFirstChild("HumanoidRootPart"))
		if t and t:IsA("BasePart") then
			return math.clamp(t.Size.Y / 2, 0.2, 25)
		end
		return 1
	end

	-- la velocidad se adapta a tu tamaño (más grande = más rápido, más chico = más lento)
	local function currentSpeed(sprint)
		return (sprint and SPRINT_SPEED or WALK_SPEED) * measureScale()
	end

	-- idle propio del stand; si AnimLib no lo acepta, se queda congelado en su última pose
	local function makeStandIdle(rig)
		local ok, an = pcall(function()
			local a = AnimLib.Animator.new()
			a.rig    = rig
			a.track  = AnimLib.Track.fromfile(assetPath("The Thinker.anim"))
			a.looped = true
			a.speed  = 1
			a.weight = 1
			return a
		end)
		return ok and an or nil
	end

	local function clearSlot(i)
		slotGen[i] = (slotGen[i] or 0) + 1   -- cancela cargas pendientes de ese slot
		slotIds[i] = nil
		local s = slots[i]
		if s and s.model then s.model:Destroy() end
		slots[i] = nil
	end

	local function clearAllStands()
		for i = 1, MAX_FRIENDS do clearSlot(i) end
	end

	local function slotOf(userId)
		for i = 1, MAX_FRIENDS do
			if slotIds[i] == userId then return i end
		end
		return nil
	end

	local function nextEmptySlot()
		for i = 1, MAX_FRIENDS do
			if slotIds[i] == nil then return i end
		end
		return nil
	end

	local function buildStand(slot, userId, gen)
		local okD, desc = pcall(Players.GetHumanoidDescriptionFromUserId, Players, userId)
		if not okD or not desc then return end

		local okR, rig = pcall(Players.CreateHumanoidModelFromDescription, Players, desc, Enum.HumanoidRigType.R6)
		if not okR or not rig then return end

		-- si se destruyó el módulo o cambiaron ese slot mientras cargaba
		if not alive or not figureRef or gen ~= slotGen[slot] then rig:Destroy() return end

		local okN, friendName = pcall(Players.GetNameFromUserIdAsync, Players, userId)
		if not alive or not figureRef or gen ~= slotGen[slot] then rig:Destroy() return end
		rig.Name = "Stand_" .. slot .. "_" .. (okN and friendName or tostring(userId))

		local hum = rig:FindFirstChildOfClass("Humanoid")
		if hum then
			hum.DisplayName = okN and friendName or ""
			hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
		end

		for _, d in ipairs(rig:GetDescendants()) do
			if d:IsA("BasePart") then
				d.CanCollide = false
				d.CanTouch   = false
				d.CanQuery   = false
				d.Massless   = true
			end
		end

		local hrp = rig:FindFirstChild("HumanoidRootPart")
		if not hrp then rig:Destroy() return end
		hrp.Anchored = true

		-- emparejar cada Motor6D de mi figura con el del stand (por nombre)
		local pairsList = {}
		local byName = {}
		for _, d in ipairs(rig:GetDescendants()) do
			if d:IsA("Motor6D") then byName[d.Name] = d end
		end
		for _, d in ipairs(figureRef:GetDescendants()) do
			if d:IsA("Motor6D") and byName[d.Name] then
				table.insert(pairsList, { src = d, dst = byName[d.Name] })
			end
		end

		-- el nuevo amigo aparece donde estaba el anterior de ese slot (si había)
		local old = slots[slot]
		if old and old.root then hrp.CFrame = old.root.CFrame end
		if old and old.model then old.model:Destroy() end

		local data = { model = rig, root = hrp, pairs = pairsList, scale = 1, idle = nil, idleT = 0 }
		data.placed = hrp.CFrame ~= CFrame.new()
		slots[slot] = data

		-- adaptar al tamaño de tu figura (escala uniforme: no se deforma)
		rig.Parent = workspace
		local S = measureScale()
		if math.abs(S - 1) > 0.01 then
			pcall(function() rig:ScaleTo(S) end)
			data.scale = S
		end
		data.idle = makeStandIdle(rig)
		rig.Parent = workspace

		-- sin colisiones: el Humanoid del stand reactiva CanCollide solo, así que se apaga y se vigila
		local sh = rig:FindFirstChildOfClass("Humanoid")
		if sh then pcall(function() sh.EvaluateStateMachine = false end) end
		data.parts = {}
		local function track(d)
			if d:IsA("BasePart") then
				d.CanCollide = false
				d.CanTouch   = false
				d.CanQuery   = false
				d.Massless   = true
				table.insert(data.parts, d)
			end
		end
		for _, d in ipairs(rig:GetDescendants()) do track(d) end
		rig.DescendantAdded:Connect(track)
	end

	-- pone a este amigo en el slot indicado (1..MAX_FRIENDS)
	local function setFriend(slot, userId)
		if not alive then return end
		slotIds[slot] = userId
		local nxt = nextEmptySlot()
		if nxt then activeSlot = nxt end
		slotGen[slot] = (slotGen[slot] or 0) + 1
		local gen = slotGen[slot]
		task.spawn(function()
			pcall(buildStand, slot, userId, gen)
		end)
	end

	-- ── MENÚ DE AMIGOS ────────────────────────────────────────────────
	local menuGui, menuFrame, menuList, menuStatus, menuSearch, menuTitle
	local menuSlotBtns = {}
	local RED  = Color3.fromRGB(200, 40, 60)
	local GRAY = Color3.fromRGB(45, 45, 55)

	local function getGuiParent()
		local ok, hui = pcall(function() return gethui() end)
		if ok and typeof(hui) == "Instance" then return hui end
		return Players.LocalPlayer:WaitForChild("PlayerGui")
	end

	-- barrita de slots 1..5: rojo = ocupado, borde blanco = el que se está llenando
	local function refreshSlotBar()
		local count = 0
		for i = 1, MAX_FRIENDS do
			local b = menuSlotBtns[i]
			local filled = slotIds[i] ~= nil
			if filled then count += 1 end
			if b then
				b.BackgroundColor3 = filled and RED or GRAY
				local st = b:FindFirstChildOfClass("UIStroke")
				if st then st.Enabled = (i == activeSlot) end
			end
		end
		if menuTitle then menuTitle.Text = "Friends (" .. count .. "/" .. MAX_FRIENDS .. ")" end
	end

	local function populateMenu()
		if not menuList then return end
		refreshSlotBar()
		for _, c in ipairs(menuList:GetChildren()) do
			if c.Name == "Row" then c:Destroy() end
		end

		-- filtrar por búsqueda
		local query = (menuSearch and menuSearch.Text or ""):lower()
		local shown = {}
		for _, f in ipairs(friends) do
			if query == "" or f.Name:lower():find(query, 1, true) then
				table.insert(shown, f)
			end
		end

		-- favoritos arriba, luego alfabético
		table.sort(shown, function(x, y)
			local fx, fy = favs[x.Id] == true, favs[y.Id] == true
			if fx ~= fy then return fx end
			return x.Name:lower() < y.Name:lower()
		end)

		-- yo (mi propio personaje) siempre va de primero
		local me = Players.LocalPlayer
		if query == "" or me.Name:lower():find(query, 1, true) or ("me"):find(query, 1, true) then
			table.insert(shown, 1, { Id = me.UserId, Name = me.Name, IsMe = true })
		end

		if not friendsLoaded then
			menuStatus.Text = "Loading friends..."
		else
			menuStatus.Text = (#friends == 0) and "No friends found" or "No results"
		end
		menuStatus.Visible = (#shown == 0) or not friendsLoaded
		menuStatus.LayoutOrder = 9999

		for i, f in ipairs(shown) do
			-- todos los slots donde está este personaje (puede estar repetido)
			local mySlots = {}
			for n = 1, MAX_FRIENDS do
				if slotIds[n] == f.Id then table.insert(mySlots, n) end
			end
			local used = #mySlots > 0

			local row = Instance.new("Frame")
			row.Name = "Row"
			row.LayoutOrder = i
			row.Size = UDim2.new(1, -8, 0, 38)
			row.BackgroundTransparency = 1
			row.Parent = menuList

			local btn = Instance.new("TextButton")
			btn.Size = f.IsMe and UDim2.new(1, 0, 1, 0) or UDim2.new(1, -44, 1, 0)
			btn.BackgroundColor3 = used and RED or GRAY
			btn.TextColor3 = Color3.new(1, 1, 1)
			btn.TextSize = 16
			btn.Font = Enum.Font.GothamMedium
			btn.TextXAlignment = Enum.TextXAlignment.Left
			btn.TextTruncate = Enum.TextTruncate.AtEnd
			btn.Text = "  " .. (f.IsMe and ("Me (" .. f.Name .. ")") or f.Name) .. (used and string.rep(" ", 6 + 4 * #mySlots) or "")
			btn.Parent = row
			Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 8)

			-- números de los slots al lado del nombre (ej: "1 3 5")
			if used then
				local parts = {}
				for _, n in ipairs(mySlots) do table.insert(parts, tostring(n)) end
				local badge = Instance.new("TextLabel")
				badge.Size = UDim2.new(0, 14 + 14 * #mySlots, 0, 26)
				badge.AnchorPoint = Vector2.new(1, 0.5)
				badge.Position = UDim2.new(1, -6, 0.5, 0)
				badge.BackgroundColor3 = Color3.fromRGB(110, 15, 30)
				badge.Text = table.concat(parts, " ")
				badge.TextColor3 = Color3.new(1, 1, 1)
				badge.TextSize = 16
				badge.Font = Enum.Font.GothamBold
				badge.Parent = btn
				Instance.new("UICorner", badge).CornerRadius = UDim.new(0, 13)
			end

			if not f.IsMe then
				local star = Instance.new("TextButton")
				star.Size = UDim2.new(0, 38, 1, 0)
				star.Position = UDim2.new(1, -38, 0, 0)
				star.BackgroundColor3 = Color3.fromRGB(45, 45, 55)
				star.Text = favs[f.Id] and "★" or "☆"
				star.TextColor3 = favs[f.Id] and Color3.fromRGB(255, 205, 40) or Color3.fromRGB(150, 150, 160)
				star.TextSize = 22
				star.Font = Enum.Font.GothamBold
				star.Parent = row
				Instance.new("UICorner", star).CornerRadius = UDim.new(0, 8)

				star.Activated:Connect(function()
					if favs[f.Id] then favs[f.Id] = nil else favs[f.Id] = true end
					saveFavs()
					populateMenu()
				end)
			end

			btn.Activated:Connect(function()
				if slotIds[activeSlot] == f.Id then
					-- el slot activo ya tiene a este personaje: tocarlo otra vez lo quita
					clearSlot(activeSlot)
				else
					-- se pone en el slot activo (puedes repetir el mismo personaje en varios slots)
					setFriend(activeSlot, f.Id)
				end
				populateMenu()
			end)
		end
	end

