	local function toggleMenu()
		if not menuFrame then return end
		menuFrame.Visible = not menuFrame.Visible
		if menuFrame.Visible then
			populateMenu()
			if not friendsLoaded then
				task.spawn(function()
					loadFriends()
					if menuFrame and menuFrame.Visible then populateMenu() end
				end)
			end
		end
	end

	-- amigo inicial: el de FRIEND_USERNAME, o uno al azar de tu lista
	local function pickInitialFriend()
		task.spawn(function()
			if FRIEND_USERNAME ~= "" then
				local ok, id = pcall(Players.GetUserIdFromNameAsync, Players, FRIEND_USERNAME)
				if ok and id then setFriend(1, id) return end
			end
			loadFriends()
			if not alive then return end
			if #friends > 0 then
				setFriend(1, friends[math.random(#friends)].Id)
			else
				setFriend(1, Players.LocalPlayer.UserId)
			end
		end)
	end

	-- botón "Random": pone amigos al azar en los slots (si lo pulsas otra vez, salen otros)
	local randomBusy = false
	function randomFriends()
		if randomBusy or not alive then return end
		randomBusy = true
		task.spawn(function()
			pcall(function()
				loadFriends()
				if not alive or #friends == 0 then return end
				local pool = {}
				for _, f in ipairs(friends) do table.insert(pool, f.Id) end
				for i = #pool, 2, -1 do
					local j = math.random(i)
					pool[i], pool[j] = pool[j], pool[i]
				end
				local n = math.min(MAX_FRIENDS, #pool)
				for i = 1, n do setFriend(i, pool[i]) end
				for i = n + 1, MAX_FRIENDS do clearSlot(i) end
				activeSlot = nextEmptySlot() or activeSlot
				if menuFrame and menuFrame.Visible then populateMenu() else refreshSlotBar() end
			end)
			randomBusy = false
		end)
	end

	-- easter egg: si alguien escribe solo "Mrclown" en el chat, los amigos 1 al 6 se vuelven Mr. Clown
	local SECRET_WORD   = "mrclown"
	local SECRET_USERID = 8732408552
	local chatConns  = {}
	local secretLast = 0

	local function secretCheck(text)
		if not alive or type(text) ~= "string" then return end
		local t = (text:match("^%s*(.-)%s*$") or ""):lower()
		if t ~= SECRET_WORD then return end
		if os.clock() - secretLast < 1 then return end
		secretLast = os.clock()
		for i = 1, MAX_FRIENDS do setFriend(i, SECRET_USERID) end
		pcall(function()
			if menuFrame and menuFrame.Visible then populateMenu() else refreshSlotBar() end
		end)
	end

	local function connectSecretChat()
		-- chat nuevo (TextChatService)
		pcall(function()
			local TCS = game:GetService("TextChatService")
			table.insert(chatConns, TCS.MessageReceived:Connect(function(msg)
				secretCheck(msg.Text)
			end))
		end)
		-- chat clásico (Player.Chatted)
		local function hook(plr)
			pcall(function()
				table.insert(chatConns, plr.Chatted:Connect(function(msg) secretCheck(msg) end))
			end)
		end
		for _, plr in ipairs(Players:GetPlayers()) do hook(plr) end
		table.insert(chatConns, Players.PlayerAdded:Connect(hook))
	end

	local function snapshotMine()
		for _, mt in ipairs(figureMotors) do
			minePose[mt] = mt.Transform
		end
	end

	local function poseDiffers(a, b)
		if (a.Position - b.Position).Magnitude > 0.02 then return true end
		return a.LookVector:Dot(b.LookVector) < 0.9995
			or a.UpVector:Dot(b.UpVector) < 0.9995
	end

	local function isOtherWriting()
		for mt, snap in pairs(minePose) do
			if mt.Parent and poseDiffers(mt.Transform, snap) then return true end
		end
		return false
	end

	-- posición (relativa a tu root, sin escalar) de cada slot: caminando y bailando
	local function slotPosition(i, blend)
		local lay  = SLOT_LAYOUT[i] or SLOT_LAYOUT[#SLOT_LAYOUT]
		local side, row = lay[1], lay[2]
		local walk = Vector3.new(
			STAND_OFFSET.X * side,
			STAND_OFFSET.Y,
			STAND_OFFSET.Z + row * ROW_SPACING)
		local dsign = STAND_DANCE_OFFSET.X < 0 and -1 or 1  -- el lado del amigo 1 (derecha)
		local back  = DANCE_BACK_SIGN                       -- hacia dónde es "atrás" al bailar
		local dance = Vector3.new(
			dsign * side * (DANCE_SIDE_DISTANCE + row * DANCE_V_STEP_SIDE),
			STAND_DANCE_OFFSET.Y,
			back * (DANCE_BACK_DISTANCE + row * ROW_SPACING_DANCE))
		return walk:Lerp(dance, blend), walk
	end

	local steppedConn
	local function noCollideStands()
		for i = 1, MAX_FRIENDS do
			local s = slots[i]
			if s and s.parts then
				for _, bp in ipairs(s.parts) do
					if bp.CanCollide then bp.CanCollide = false end
					if bp.CanTouch   then bp.CanTouch   = false end
					if bp.CanQuery   then bp.CanQuery   = false end
				end
			end
		end
	end

	-- corre al final del frame (RenderPriority.Last) para copiar la pose final
	local function updateStand(dt)
		if not figureRef then return end
		local any = false
		for i = 1, MAX_FRIENDS do
			local s = slots[i]
			if s and s.root and s.root.Parent then any = true break end
		end
		if not any then return end
		local root = figureRef:FindFirstChild("HumanoidRootPart")
		if not root then return end

		local S = measureScale()

		-- ¿estoy bailando?
		if isOtherWriting() then
			danceHold = 0.3
		else
			danceHold = math.max(0, danceHold - dt)
		end
		local dancing = danceHold > 0
		danceBlend += ((dancing and 1 or 0) - danceBlend) * (1 - math.exp(-6 * dt))

		standT += dt
		local locomoting = not dancing and (currentAnim == walkAnim or currentAnim == runAnim)

		for i = 1, MAX_FRIENDS do
			local s = slots[i]
			if s and s.root and s.root.Parent then
				-- si cambias tu tamaño, los amigos también
				if math.abs(S - s.scale) > 0.02 then
					pcall(function() s.model:ScaleTo(S) end)
					s.scale = S
					s.idle  = makeStandIdle(s.model)
				end
				local sc = s.scale

				local pos = slotPosition(i, danceBlend)
				local bob = math.sin(standT * 2 + i) * 0.25 * (1 - danceBlend) * sc

				local target = root.CFrame * CFrame.new(pos * sc) * CFrame.new(0, bob, 0) -- las distancias se multiplican por el tamaño

				if not s.placed then
					s.root.CFrame = target
					s.placed = true
				else
					local a = 1 - math.exp(-STAND_FOLLOW * dt)
					s.root.CFrame = s.root.CFrame:Lerp(target, a)
				end

				-- los amigos NO caminan ni corren: cuando tú caminas/corres se quedan parados (idle).
				-- Todo lo demás (idle tuyo y bailes) sí lo copian exacto.
				if locomoting then
					s.idleT += dt
					if s.idle then pcall(function() s.idle:Step(s.idleT) end) end
				else
					s.idleT = 0
					for _, p in ipairs(s.pairs) do
						if p.src.Parent and p.dst.Parent then
							p.dst.C0        = p.src.C0
							p.dst.C1        = p.src.C1
							p.dst.Transform = p.src.Transform
						end
					end
				end
			end
		end
	end

	-- Init
	m.Init = function(figure)
		figureRef = figure
		alive     = true

		installAssets()

		idleAnim = loadLoopAnim("The Thinker.anim")
		runAnim  = loadLoopAnim("run.anim")
		walkAnim = loadLoopAnim("walk.anim")
		local okStun, sa = pcall(loadAnim, "stun.anim")
		stunAnim = okStun and sa or nil
		local okJ, ja = pcall(loadAnim, "jump.anim")
		jumpAnim = okJ and ja or nil
		local okF, fa = pcall(loadAnim, "fall.anim")
		fallAnim = okF and fa or nil
		animLen = {}
		if stunAnim then animLen[stunAnim] = STUN_ANIM_LEN end
		if jumpAnim then animLen[jumpAnim] = 0.05 end   -- jump.anim: 2 keyframes (0 y 0.05 s)
		if fallAnim then animLen[fallAnim] = 0 end      -- fall.anim: 1 keyframe, se queda en esa pose

		play(idleAnim)

		local hum = figure:FindFirstChildOfClass("Humanoid")
		if hum then hum.WalkSpeed = currentSpeed(false) end

		-- Run button: keybind (LeftShift) + on-screen button, hold to sprint
		ContextActions:BindAction("Uhhhhhh_SoyRun", function(_, state, _)
			if state == Enum.UserInputState.Begin then
				isSprinting = true
				local hum2 = figureRef and figureRef:FindFirstChildOfClass("Humanoid")
				if hum2 and stunTime <= 0 then hum2.WalkSpeed = currentSpeed(true) end
			elseif state == Enum.UserInputState.End then
				isSprinting = false
				local hum2 = figureRef and figureRef:FindFirstChildOfClass("Humanoid")
				if hum2 and stunTime <= 0 then hum2.WalkSpeed = currentSpeed(false) end
			end
		end, true, Enum.KeyCode.LeftShift)
		ContextActions:SetTitle("Uhhhhhh_SoyRun", "Run")
		ContextActions:SetPosition("Uhhhhhh_SoyRun", UDim2.new(1, -130, 1, -130))

		-- Botón junto al de salto: abre el menú de amigos (tecla G en PC)
		loadFavs()
		pcall(createMenu)
		ContextActions:BindAction("Uhhhhhh_SoyFriend", function(_, state, _)
			if state == Enum.UserInputState.Begin then toggleMenu() end
		end, true, Enum.KeyCode.G)
		ContextActions:SetTitle("Uhhhhhh_SoyFriend", "Friend")
		ContextActions:SetPosition("Uhhhhhh_SoyFriend", UDim2.new(1, -130, 1, -210))

		figureMotors = {}
		for _, d in ipairs(figure:GetDescendants()) do
			if d:IsA("Motor6D") then table.insert(figureMotors, d) end
		end

		RunService:BindToRenderStep("Uhhhhhh_SoyStand", Enum.RenderPriority.Last.Value, updateStand)
		steppedConn = RunService.Stepped:Connect(noCollideStands)

		-- Botón de música: quitar / poner (tecla M en PC)
		pcall(createMusic)
		ContextActions:BindAction("Uhhhhhh_SoyMusic", function(_, state, _)
			if state == Enum.UserInputState.Begin then setMusic(not musicOn) end
		end, true, Enum.KeyCode.M)
		ContextActions:SetTitle("Uhhhhhh_SoyMusic", "Remove music")
		ContextActions:SetPosition("Uhhhhhh_SoyMusic", UDim2.new(1, -130, 1, -290))

		-- (ya no aparece ningún amigo al activar el moveset: los pones con "Friend" o "Random")
		connectSecretChat()
	end

	-- Update
	m.Update = function(dt, figure)
		if not figureRef then return end
		local hum = figureRef:FindFirstChildOfClass("Humanoid")
		if not hum then return end

		updateMusic(dt, isOtherWriting())

		-- ── STUN: medir la caída y, si fue desde muy alto, aturdirse ─────
		if stunTime <= 0 and stunAnim then
			local root = figureRef:FindFirstChild("HumanoidRootPart")
			local st   = hum:GetState()
			if root then
				if st == Enum.HumanoidStateType.Climbing or st == Enum.HumanoidStateType.Swimming
					or st == Enum.HumanoidStateType.Seated or st == Enum.HumanoidStateType.Dead then
					airborne = false
				elseif hum.FloorMaterial == Enum.Material.Air then
					local y = root.Position.Y
					if not airborne then
						airborne, peakY = true, y
					elseif y > peakY then
						peakY = y
					end
				elseif airborne then
					airborne = false
					local drop = peakY - root.Position.Y
					if drop >= STUN_FALL_HEIGHT * measureScale() then startStun() end
				end
			end
		end

		-- mientras dura el stun no puedes caminar, correr, saltar ni girar
		if stunTime > 0 then
			stunTime -= dt
			lockHumanoid(hum)
			hum.WalkSpeed  = 0
			hum.JumpPower  = 0
			hum.JumpHeight = 0
			hum.AutoRotate = false
			play(stunAnim, STUN_FADE)
			stepAnims(dt, false)
			snapshotMine()
			if stunTime <= 0 then unlockHumanoid(hum) end
			return
		end

		-- ── LOCOMOTION ────────────────────────────────────────────────
		hum.WalkSpeed = currentSpeed(isSprinting)

		local airSt = hum:GetState()
		if airSt == Enum.HumanoidStateType.Jumping and jumpAnim then
			play(jumpAnim, 0.08)          -- saltando
		elseif airSt == Enum.HumanoidStateType.Freefall and fallAnim then
			play(fallAnim, 0.15)          -- cayendo
		elseif hum.MoveDirection.Magnitude > 0 then
			play(isSprinting and runAnim or walkAnim)
		else
			play(idleAnim)
		end

		stepAnims(dt, hum.MoveDirection.Magnitude > 0)
		snapshotMine()
	end

	-- Destroy
	m.Destroy = function(figure)
		alive = false
		ContextActions:UnbindAction("Uhhhhhh_SoyRun")
		ContextActions:UnbindAction("Uhhhhhh_SoyFriend")
		ContextActions:UnbindAction("Uhhhhhh_SoyMusic")
		for _, c in ipairs(chatConns) do pcall(function() c:Disconnect() end) end
		chatConns = {}
		if music then music:Destroy() end
		music, musicOn, musicHold = nil, true, 0
		pcall(function() RunService:UnbindFromRenderStep("Uhhhhhh_SoyStand") end)
		if steppedConn then steppedConn:Disconnect() steppedConn = nil end
		clearAllStands()
		if menuGui then menuGui:Destroy() end
		menuGui, menuFrame, menuList, menuStatus, menuSearch, menuTitle = nil, nil, nil, nil, nil, nil
		menuSlotBtns, slotIds, slotGen, activeSlot = {}, {}, {}, 1
		minePose, figureMotors = {}, {}
		accel, fadeAlpha, fadeFromAnim, fadeFromPose, currentAnim = 0, 1, nil, nil, nil
		local hum = figure and figure:FindFirstChildOfClass("Humanoid")
		if hum then unlockHumanoid(hum) end
		stunTime, airborne, stunAnim, jumpAnim, fallAnim, animLen = 0, false, nil, nil, nil, {}
		if hum then hum.WalkSpeed = 10 end
	end

	return m
end)

return modules
